import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const DMPage = () => {
  const [senders, setSenders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("Authentication required. Please log in.");
      navigate("/login");
      return;
    }

    fetch("http://localhost:5001/api/conversations/senders", {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
    })
      .then((res) => (res.ok ? res.json() : Promise.reject("Failed to fetch senders")))
      .then((data) => {
        setSenders(data.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching senders:", err);
        setError("Failed to load conversations.");
        setLoading(false);
      });
  }, [navigate]);

  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;

  return (
    <div className="dm-page">
      <h2>Direct Messages</h2>
      {senders.length === 0 ? (
        <p>No messages received yet.</p>
      ) : (
        <ul className="senders-list">
          {senders.map((sender) => (
            <li key={sender._id} className="sender-item" onClick={() => navigate(`/chat/${sender._id}`)}>
              <img src={sender.image || "default-user.png"} alt={sender.name} className="sender-img" />
              <div className="sender-info">
                <h3>{sender.name}</h3>
                <p>{sender.email}</p>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default DMPAGE2;
